const Company = require('../models/Company');
const Interview = require('../models/Interview');
const { geocodeAddress, GeocodingError } = require('../services/geocoding');

// Coordinates are generated by the server, never supplied by a client.
const companyFields = ['name', 'address', 'industry', 'website', 'description', 'tel'];
const companyInput = (body = {}) => {
    const data = {};
    companyFields.forEach(field => {
        if (Object.prototype.hasOwnProperty.call(body, field)) {
            data[field] = body[field];
        }
    });
    return data;
};

function companyWriteError(res, error) {
    if (error instanceof GeocodingError) {
        return res.status(error.statusCode).json({ success: false, message: error.message });
    }
    const invalid = error.name === 'ValidationError' || error.name === 'CastError' || error.code === 11000;
    if (invalid) {
        return res.status(400).json({ success: false, message: 'Invalid or duplicate company data' });
    }
    return res.status(500).json({ success: false, message: 'Cannot save company' });
}

// Mean Earth radius in km; $centerSphere takes its radius in radians (distance / Earth radius).
const EARTH_RADIUS_KM = 6378.1;

// Query parameters handled by getCompanies itself, not by the generic field filter.
const customParams = ['select', 'sort', 'page', 'limit', 'name', 'industry', 'lat', 'lng', 'radiusKm'];

// Escape regex special characters so user input is matched literally
const escapeRegex = (text) => text.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

// Only accept plain string query values (ignore objects/arrays)
const queryText = (value) => (typeof value === 'string' ? value.trim() : '');

// Strict number parsing: rejects '', '12abc', 'Infinity'
const toNumber = (text) => (text !== '' && Number.isFinite(Number(text)) ? Number(text) : NaN);

// Builds the search filter from req.query. Returns { filter } or { error } (a 400 message).
const buildCompanyFilter = (query) => {
    const reqQuery = { ...query };
    customParams.forEach(param => delete reqQuery[param]);

    //Generic field filters: only turn operator keys like "gt": into "$gt":, never values
    let queryStr = JSON.stringify(reqQuery);
    queryStr = queryStr.replace(/"(gt|gte|lt|lte|in)":/g, (match, op) => `"$${op}":`);
    const filter = JSON.parse(queryStr);

    //Name: partial, case-insensitive, matched literally
    const name = queryText(query.name);
    if (name) {
        filter.name = { $regex: escapeRegex(name), $options: 'i' };
    }

    //Industry: one value, or several separated by commas (e.g. Software,Finance)
    const industryText = queryText(query.industry);
    if (industryText) {
        const industries = [];
        for (const item of industryText.split(',').map(s => s.trim()).filter(Boolean)) {
            const match = Company.INDUSTRIES.find(i => i.toLowerCase() === item.toLowerCase());
            if (!match) {
                return { error: `Invalid industry '${item}'. Must be one of: ${Company.INDUSTRIES.join(', ')}` };
            }
            industries.push(match);
        }
        filter.industry = { $in: industries };
    }

    //Distance: straight-line distance from (lat, lng), all three parameters required together
    const geoParams = ['lat', 'lng', 'radiusKm'];
    const supplied = geoParams.filter(p => query[p] !== undefined);
    if (supplied.length > 0) {
        if (supplied.length < geoParams.length) {
            return { error: 'lat, lng and radiusKm must be provided together' };
        }
        const lat = toNumber(queryText(query.lat));
        const lng = toNumber(queryText(query.lng));
        const radiusKm = toNumber(queryText(query.radiusKm));
        if (Number.isNaN(lat) || lat < -90 || lat > 90) {
            return { error: 'lat must be a number between -90 and 90' };
        }
        if (Number.isNaN(lng) || lng < -180 || lng > 180) {
            return { error: 'lng must be a number between -180 and 180' };
        }
        if (Number.isNaN(radiusKm) || radiusKm <= 0) {
            return { error: 'radiusKm must be a positive number' };
        }
        // $geoWithin (unlike $near) also works with countDocuments for pagination totals.
        // GeoJSON order is [longitude, latitude].
        filter.location = {
            $geoWithin: { $centerSphere: [[lng, lat], radiusKm / EARTH_RADIUS_KM] }
        };
    }

    return { filter };
};

//@desc    Get all companies (filter by name, industry and distance from a point)
//@route   GET /api/v1/companies?name=&industry=&lat=&lng=&radiusKm=
//access   Private
exports.getCompanies = async (req, res) => {
    const { filter, error } = buildCompanyFilter(req.query);
    if (error) {
        return res.status(400).json({ success: false, message: error });
    }

    let query = Company.find(filter).populate('interviews');

    //Select Fields
    if (req.query.select) {
        const fields = req.query.select.split(',').join(' ');
        query = query.select(fields);
    }

    //Sort Fields
    if (req.query.sort) {
        const sortBy = req.query.sort.split(',').join(' ');
        query = query.sort(sortBy);
    } else{
        query = query.sort('-createdAt');
    }

    //Pagination
    const page = parseInt(req.query.page, 10) || 1;
    const limit = parseInt(req.query.limit, 10) || 25;
    const startIndex = (page - 1) * limit;
    const endIndex = page * limit;

    try {
        const total = await Company.countDocuments(filter);
        query = query.skip(startIndex).limit(limit);
        //Execute query
        const companies = await query;

        //Pagination result
        const pagination = {};
        if (endIndex < total) {
            pagination.next = {
                page: page + 1,
                limit
            };
        }

        if (startIndex > 0) {
            pagination.prev = {
                page: page - 1,
                limit
            };
        }

        res.status(200).json({ success: true, count: companies.length, total, pagination, data: companies });
    }
    catch (err) {
        res.status(400).json({ success: false });
    }
}

//@desc    Get a single company
//@route   GET /api/v1/companies/:id
//access   Public
exports.getCompany = async (req, res) => {
    try {
        const company = await Company.findById(req.params.id);
        if (!company) {
            return res.status(400).json({ success: false });
        }
        res.status(200).json({ success: true, data: company });
    } catch (err) {
        res.status(400).json({ success: false });
    }
};

//@desc    Create new company
//@route   POST /api/v1/companies
//access   Private
exports.createCompany = async (req, res) => {
    try {
        const company = new Company(companyInput(req.body));
        await company.validate();
        company.location = await geocodeAddress(company.address);
        await company.save();
        res.status(201).json({ success: true, data: company });
    } catch (err) {
        return companyWriteError(res, err);
    }
}

//@desc    Update company
//@route   PUT /api/v1/companies/:id
//access   Private
exports.updateCompany = async (req, res) => {
    try {
        const company = await Company.findById(req.params.id);
        if (!company) {
            return res.status(400).json({ success: false });
        }
        const previousAddress = company.address;
        company.set(companyInput(req.body));
        await company.validate();
        // Resubmitting an old company's address also fills missing coordinates.
        const addressChanged = company.address !== previousAddress;
        const needsLocation = !company.location && Object.prototype.hasOwnProperty.call(req.body || {}, 'address');
        if (addressChanged || needsLocation) {
            company.location = await geocodeAddress(company.address);
        }
        await company.save();
        res.status(200).json({ success: true, data: company });
    } catch (err) {
        return companyWriteError(res, err);
    }
};

//@desc    Delete company
//@route   DELETE /api/v1/companies/:id
//access   Private
exports.deleteCompany = async (req, res) => {
    try {
        const company = await Company.findById(req.params.id);

        if (!company) {
            return res.status(404).json({ success: false, message: `Company not found with id of ${req.params.id}` });
        }

        await Interview.deleteMany({ company: req.params.id });
        await Company.deleteOne({ _id: req.params.id });

        res.status(200).json({ success: true, data: {} });
    } catch (err) {
        res.status(400).json({ success: false });
    }
}
